def valid_browser_origin(scheme: str, host_header: str, origin_header: str) -> bool:
    try:
        request_host = urlsplit("//" + host_header)
        origin = urlsplit(origin_header)
        hostname = request_host.hostname
        request_host.port  # Validate the optional port.
        if hostname is None or request_host.username is not None or request_host.password is not None or \
                request_host.path or request_host.query or request_host.fragment:
            return False
        if origin.scheme != scheme or origin.netloc != host_header:
            return False
        if origin.username is not None or origin.password is not None or origin.path or origin.query or origin.fragment:
            return False
        if hostname.lower().rstrip(".") == "localhost":
            return True
        return ipaddress.ip_address(hostname).is_loopback
    except ValueError:
        return False

def valid_lsp_peer(host: str) -> bool:
    """Only the actual loopback TCP peer may use filesystem-aware language help."""
    try:
        return ipaddress.ip_address(host).is_loopback
    except ValueError:
        return False


@asynccontextmanager
async def lifespan(app: FastAPI):
    async with RendererPool(workers=2, workspace=str(LSP_WORKSPACE)) as pool:
        app.state.renderer_pool = pool
        yield


app = FastAPI(title="Markata live editor", lifespan=lifespan)
presentation = appearance(asset_base="/appearance", workspace=str(LSP_WORKSPACE))


class RenderRequest(BaseModel):
    markdown: str = Field(max_length=200_000)
    appearance: dict[str, str] = Field(default_factory=dict)
    include_document: bool = True


@app.post("/render")
async def preview(request: RenderRequest):
    if len(request.markdown.encode('utf-8')) > 200_000:
        return JSONResponse({'error': 'Document exceeds 200,000 UTF-8 bytes.'}, status_code=422)
    allowed = {'data-theme': 'mode', 'data-palette': 'palette', 'data-aesthetic': 'aesthetic',
               'data-fontpack': 'fontpack', 'data-text-size': 'text_size'}
    try:
        presentation.validate(request.appearance)
        options = {allowed[key]: value for key, value in presentation.defaults.items() if key in allowed}
        options.update({allowed[key]: value for key, value in request.appearance.items() if key in allowed})
    except ValueError as error:
        return JSONResponse({"error": str(error)}, status_code=422)
    started = perf_counter()
    try:
        result = await app.state.renderer_pool.render(request.markdown, inline_assets=True, unsafe=True, timeout=15)
    except RenderError as error:
        return JSONResponse({"error": str(error)}, status_code=422)
    render_ms = (perf_counter() - started) * 1000
    document = result.document(title="Markdown preview", appearance=presentation, appearance_bridge=True, **options) if request.include_document else ""
    return JSONResponse({"document": document or None, "html": result.html,
                         "feature_head_html": result.feature_head_html,
                         "body_end_html": result.body_end_html,
                         "render_ms": round(render_ms, 2),
                         "input_bytes": len(request.markdown.encode()),
                         "html_bytes": len(result.html.encode()),
                         "document_bytes": len(document.encode())},
                        headers={"Server-Timing": f"markata;dur={render_ms:.2f}"})


def require_local_workspace(request: Request):
    if request.client is None or not ipaddress.ip_address(request.client.host).is_loopback:
        raise HTTPException(status_code=403, detail="Local workspace access required")
    host = request.headers.get("host", "")
    if not valid_browser_origin(request.url.scheme, host, request.headers.get("origin", request.url.scheme + "://" + host)):
        raise HTTPException(status_code=403, detail="Local workspace access required")


@app.get("/workspace")
async def workspace_index(request: Request, metadata: bool = False):
    require_local_workspace(request)
    try:
        data = await asyncio.to_thread(workspace_files, str(LSP_WORKSPACE), metadata=metadata)
        data["root"] = str(LSP_WORKSPACE)
        return data
    except RenderError as error:
        raise HTTPException(status_code=422, detail=str(error)) from error


@app.get("/workspace/file")
async def workspace_source(request: Request, path: str):
    require_local_workspace(request)
    try:
        return await asyncio.to_thread(workspace_files, str(LSP_WORKSPACE), path=path)
    except RenderError as error:
        raise HTTPException(status_code=404, detail=str(error)) from error


@app.get("/workspace/image")
async def workspace_image(request: Request, path: str):
    require_local_workspace(request)
    static_root = (LSP_WORKSPACE / "static").resolve()
    candidate = Path(path)
    if candidate.is_absolute() or candidate.suffix.lower() not in {".jpg", ".jpeg", ".png", ".webp", ".gif", ".avif"}:
        raise HTTPException(status_code=404, detail="Image not found")
    resolved = (static_root / candidate).resolve()
    if not resolved.is_relative_to(static_root) or not resolved.is_file() or resolved.stat().st_size > 15 * 1024 * 1024:
        raise HTTPException(status_code=404, detail="Image not found")
    return FileResponse(resolved, headers={"Cache-Control": "no-store"})


@app.get("/", response_class=HTMLResponse)
async def index():
    cm_files = ['addon/hint/show-hint.css', 'lib/codemirror.css', 'lib/codemirror.js', 'mode/xml/xml.js', 'mode/markdown/markdown.js', 'mode/gfm/gfm.js', 'mode/javascript/javascript.js', 'mode/python/python.js', 'mode/css/css.js', 'mode/htmlmixed/htmlmixed.js', 'addon/mode/overlay.js', 'addon/edit/matchbrackets.js', 'addon/hint/show-hint.js', 'keymap/vim.js', 'keymap/emacs.js', 'keymap/sublime.js']
    cm_tags = ''.join('<link rel="stylesheet" href="/appearance/codemirror/' + n + '">' if n.endswith('.css') else '<script src="/appearance/codemirror/' + n + '"></script>' for n in cm_files)
    cm_tags += '<link rel="stylesheet" href="/appearance/command-palette.css"><script src="/appearance/command-catalog.js"></script><script src="/appearance/command-palette.js"></script>'
    cm_tags += '<script src="/appearance/site-tree.js"></script>'
    page = PAGE.replace('<body>' , '<body data-example-url="/appearance/command-palette-example.md">', 1)
    page = page.replace('<head>', '<head>' + cm_tags + '<link rel="stylesheet" href="/editor/lsp.css"><script src="/editor/lsp.js"></script>', 1).replace('</head>', presentation.controls_head_html + '<link rel="stylesheet" href="/appearance/site-tree.css"></head>', 1)
    page = page.replace('<button id="open"', presentation.picker_html + '<button id="open"', 1)
    for key, value in presentation.defaults.items():
        tag = re.search(r'<html[^>]*>', page).group(0)
        updated = re.sub(r' ' + re.escape(key) + r'="[^"]*"', '', tag)
        page = page.replace(tag, updated[:-1] + ' ' + key + '="' + escape(value, quote=True) + '">', 1)
    page = page.replace('</body>', presentation.body_end_html + '</body>', 1)
    def version_asset(match):
        name = match.group(2)
        try:
            content = editor_asset_bytes(name)
        except (KeyError, OSError):
            return match.group(0)
        return match.group(1) + name + '?v=' + hashlib.sha256(content).hexdigest()[:16] + '"'
    return re.sub(r'((?:src|href)="/appearance/)([^"?]+)"', version_asset, page)


